"""Yield an iterable's items in batches of at most ``n``."""

from itertools import islice


def batched(iterable, n):
    if n < 1:
        raise ValueError("n must be at least one")

    iterator = iter(iterable)
    while batch := list(islice(iterator, n)):
        yield batch

